#!/bin/bash
# Survey occurrences of the accidentally-posted string without printing the string itself.
DB="$HOME/.local/share/opencode/opencode.db"
MSG="msg_1ddbbe35c001rqwtAxB6F3XHyJ"
RO="file:${DB}?mode=ro"

needle() {
  sqlite3 "$RO" "SELECT json_extract(data,'\$.text') FROM session_message WHERE id='$MSG';"
}

N="$(needle)"
if [ -z "$N" ]; then echo "ERROR: could not read needle"; exit 1; fi
echo "needle length: ${#N}"

TABLES=$(sqlite3 "$RO" "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';")

echo "--- table/column occurrence counts ---"
for t in $TABLES; do
  cols=$(sqlite3 "$RO" "PRAGMA table_info('$t');" | cut -d'|' -f2)
  for c in $cols; do
    n=$(sqlite3 "$RO" "SELECT COUNT(*) FROM \"$t\" WHERE instr(\"$c\", (SELECT json_extract(data,'\$.text') FROM session_message WHERE id='$MSG'))>0;" 2>/dev/null)
    if [ -n "$n" ] && [ "$n" != "0" ]; then
      echo "$t.$c : $n"
    fi
  done
done

echo "--- other files under ~/.local/share/opencode ---"
find "$HOME/.local/share/opencode" -type f ! -name 'opencode.db*' -print0 \
  | xargs -0 grep -c -F -e "$N" 2>/dev/null | grep -v ':0$'

echo "--- done ---"
