One important catch: the token happens to be the same string as the usual redaction marker, so replacing it with that marker wouldn't actually change the stored bytes. Let me use a distinct marker, deriving the token from the DB itself so it never gets echoed again.
$ cd ~/.local/share/opencode && python3 - <<'EOF'
import sqlite3, json
MARK = "[removed by request]"
con = sqlite3.connect("opencode.db", timeout=15)
con.execute("PRAGMA busy_timeout=15000")
cur = con.cursor()
# derive the token from the stored original message instead of typing it
tok = cur.execute("SELECT json_extract(data,'$.text') FROM session_message WHERE id=?", ("msg_1dddb7d08001omN8g7TaZSPKZM",)).fetchone()[0]
print("token length:", len(tok), "distinct from marker:", tok != MARK)
cur.execute("BEGIN IMMEDIATE")
rows = cur.execute("SELECT id, data FROM session_message WHERE instr(data, ?)>0", (tok,)).fetchall()
for rid, data in rows:
    new = data.replace(tok, MARK)
    json.loads(new)                      # must stay valid JSON
    cur.execute("UPDATE session_message SET data=? WHERE id=?", (new, rid))
con.commit()
print("rows rewritten:", len(rows))
print("rows still containing token:", cur.execute("SELECT count(*) FROM session_message WHERE instr(data, ?)>0", (tok,)).fetchone()[0])
con.close()

# same token in the two stray files I scrubbed earlier
for p in ["./shell/5dadc7690882ac4807b80c8848691751d770e91e/sh_1dddcf7c1001W7JYZwTyu4rXR2.out", "./log/opencode.log"]:
    d = open(p, encoding="utf-8", errors="surrogateescape").read()
    if tok in d:
        open(p, "w", encoding="utf-8", errors="surrogateescape").write(d.replace(tok, MARK))
        print("rewrote", p)
